/**
 * ChatView — 事件驱动的对话视图。
 *
 * 借鉴 deepseek-harness 的 ChatView 模式：
 * - 遍历事件列表，通过 ConversationNode 注册表匹配渲染器
 * - 智能跟随滚动（用户在底部时跟随，自由滚动时不强制）
 * - Turn 级别状态指示
 */
import { useCallback, useEffect, useRef, useState } from 'react'
import { type SessionEvent } from './types'
import { matchNode, type ConversationNodeDef } from './nodes/registry'
import { TurnStatus } from './TurnStatus'
import { cn } from '@/lib/utils'

interface ChatViewProps {
  events: SessionEvent[]
  nodes?: ConversationNodeDef[]
  isStreaming?: boolean
  turnIndex?: number
  className?: string
}

export function ChatView({
  events,
  nodes,
  isStreaming = false,
  turnIndex = 0,
  className,
}: ChatViewProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const bottomRef = useRef<HTMLDivElement>(null)
  const [userScrolled, setUserScrolled] = useState(false)

  // 智能跟随滚动：用户在底部时自动跟随
  const checkIsAtBottom = useCallback(() => {
    const el = containerRef.current
    if (!el) return true
    return el.scrollHeight - el.scrollTop - el.clientHeight < 80
  }, [])

  const scrollToBottom = useCallback((smooth = true) => {
    bottomRef.current?.scrollIntoView({ behavior: smooth ? 'smooth' : 'instant' })
  }, [])

  // 监听滚动，判断用户是否主动离开底部
  useEffect(() => {
    const el = containerRef.current
    if (!el) return

    const onScroll = () => {
      setUserScrolled(!checkIsAtBottom())
    }
    el.addEventListener('scroll', onScroll, { passive: true })
    return () => el.removeEventListener('scroll', onScroll)
  }, [checkIsAtBottom])

  // 新事件到来时，如果用户在底部则自动跟随
  useEffect(() => {
    if (!userScrolled) {
      scrollToBottom(true)
    }
  }, [events.length, userScrolled, scrollToBottom])

  return (
    <div className={cn('flex flex-col h-full', className)}>
      {/* 事件列表 */}
      <div ref={containerRef} className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
        {events.length === 0 && !isStreaming && (
          <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
            开始对话
          </div>
        )}

        {events.map((event, idx) => {
          const nodeDef = matchNode(event, nodes)
          if (!nodeDef) return null
          return (
            <div key={event.seq ?? idx} className="conversation-node-wrapper">
              {nodeDef.render({ event, index: idx })}
            </div>
          )
        })}

        {/* 流式状态指示 */}
        {isStreaming && (
          <TurnStatus turn={turnIndex} />
        )}

        <div ref={bottomRef} />
      </div>
    </div>
  )
}
